from tornado.util import Configurable

class TestConfigurable(Configurable):
    @classmethod
    def configurable_base(cls):
        return TestConfigurable
    @classmethod
    def configurable_default(cls):
        return TestConfig1

class TestConfig1(TestConfigurable):
    def initialize(self, a=None):
        self.a = a

class TestConfig3(TestConfigurable):
    @classmethod
    def configurable_base(cls):
        return TestConfig3
    @classmethod
    def configurable_default(cls):
        return TestConfig3A

class TestConfig3A(TestConfig3):
    def initialize(self, a=None):
        self.a = a

class TestConfig3B(TestConfig3):
    def initialize(self, b=None):
        self.b = b

TestConfigurable.configure(TestConfig3, a=1)
obj = TestConfigurable()
assert isinstance(obj, TestConfig3A), type(obj)
assert obj.a == 1
print("ok:", type(obj).__name__, obj.a)
EOF
python /tmp/repro.py && python -m pytest tornado/test/util_test.py -q 2>&1 | tail -3

cd /workspace && cat > /tmp/repro2.py <<'EOF'
from tornado.util import Configurable

class TestConfigurable(Configurable):
    @classmethod
    def configurable_base(cls): return TestConfigurable
    @classmethod
    def configurable_default(cls): return TestConfig1

class TestConfig1(TestConfigurable):
    def initialize(self, a=None): self.a = a

class TestConfig3(TestConfigurable):
    @classmethod
    def configurable_base(cls): return TestConfig3
    @classmethod
    def configurable_default(cls): return TestConfig3A

class TestConfig3A(TestConfig3):
    def initialize(self, a=None, b=None): self.a = a; self.b = b

class TestConfig3B(TestConfig3):
    def initialize(self, a=None, b=None): self.b = b

TestConfigurable.configure(TestConfig3, a=1)
obj = TestConfigurable()
assert isinstance(obj, TestConfig3A) and obj.a == 1

TestConfig3.configure(TestConfig3B, b=2)
obj2 = TestConfigurable()
assert isinstance(obj2, TestConfig3B) and obj2.b == 2 and obj2.a == 1

saved = TestConfig3._save_configuration()
TestConfig3.configure(TestConfig3A)
assert isinstance(TestConfig3(), TestConfig3A)
TestConfig3._restore_configuration(saved)
assert isinstance(TestConfig3(), TestConfig3B)

# default path unaffected: plain configurable still works
class Other(Configurable):
    @classmethod
    def configurable_base(cls): return Other
    @classmethod
    def configurable_default(cls): return OtherImpl
class OtherImpl(Other):
    def initialize(self): pass
assert isinstance(Other(), OtherImpl)
print("all ok")
EOF
python /tmp/repro2.py && python -m pytest tornado/test/util_test.py tornado/test/import_test.py -q 2>&1 | tail -2
